html:
{#- Device master record, the controlled index of the medical device file (module 31; URS-QMS-030; ISO 13485 4.2.3, 4.2.4). -#}
{%- set controlled = doc.status == "Current" and doc.docstatus == 1 -%}
<style>
	.mds-dmr { font-size: 11px; }
	.mds-dmr .mds-banner { padding: 6px 10px; border: 2px solid; font-weight: bold; margin-bottom: 12px; }
	.mds-dmr .mds-controlled { border-color: #1a7f37; color: #1a7f37; }
	.mds-dmr .mds-uncontrolled { border-color: #b42318; color: #b42318; }
	.mds-dmr table { width: 100%; border-collapse: collapse; margin-bottom: 12px; }
	.mds-dmr th, .mds-dmr td { border: 1px solid #c8c8c8; padding: 4px 6px; text-align: left; vertical-align: top; }
	.mds-dmr th { background: #f4f4f4; }
	.mds-dmr .mds-label { width: 28%; }
	.mds-dmr .mds-stale { color: #b42318; font-weight: bold; }
</style>
<div class="mds-dmr">
	{%- if controlled %}
	<div class="mds-banner mds-controlled">
		{{ _("CONTROLLED INDEX") }} · {{ _("Printed on {0}. Check the system for the current revision before use.").format(frappe.utils.format_datetime(frappe.utils.now_datetime())) }}
	</div>
	{%- else %}
	<div class="mds-banner mds-uncontrolled">
		{{ _("NOT FOR USE") }} · {{ _("Status: {0}").format(_(doc.status)) }}{% if doc.superseded_by %} · {{ _("Superseded by {0}").format(doc.superseded_by | e) }}{% endif %}{% if doc.out_of_date_since %} · {{ _("Out of date since {0}").format(frappe.utils.format_datetime(doc.out_of_date_since)) }}{% endif %}
	</div>
	{%- endif %}
	<h3>{{ _("Device master record") }} {{ doc.name | e }} · {{ _("Revision") }} {{ doc.revision | e }}</h3>
	<table>
		<tr><th class="mds-label">{{ _("Finished good") }}</th><td>{{ doc.item | e }} · {{ (doc.item_name or "") | e }}</td></tr>
		<tr><th class="mds-label">{{ _("Device class (MDR 2017)") }}</th><td>{{ (doc.device_class or "") | e }}</td></tr>
		<tr><th class="mds-label">{{ _("Supplied sterile") }}</th><td>{{ _(doc.sterile) if doc.sterile else "" }}</td></tr>
		<tr><th class="mds-label">{{ _("UDI device identifier (GTIN)") }}</th><td>{{ (doc.udi_di or "") | e }}</td></tr>
		<tr><th class="mds-label">{{ _("Device lifetime (years)") }}</th><td>{{ doc.device_lifetime_years or "" }}</td></tr>
		<tr><th class="mds-label">{{ _("Status") }}</th><td>{{ _(doc.status) | e }}</td></tr>
		<tr><th class="mds-label">{{ _("Supersedes") }}</th><td>{{ (doc.supersedes or "") | e }}</td></tr>
		<tr><th class="mds-label">{{ _("What changed in this revision") }}</th><td>{{ (doc.summary_of_change or _("First issue")) | e }}</td></tr>
	</table>
	{%- for heading in doc.headings %}
	<h4>{{ _(heading.heading) | e }}{% if heading.not_applicable %} · {{ _("Not applicable") }}{% endif %}</h4>
	<p>{{ (heading.content or "") | e }}</p>
	{%- set rows = doc.elements | selectattr("heading", "equalto", heading.heading) | list %}
	{%- if rows %}
	<table>
		<tr><th>{{ _("Element") }}</th><th>{{ _("Record") }}</th><th>{{ _("Title") }}</th><th>{{ _("Version approved") }}</th><th>{{ _("Changed under") }}</th></tr>
		{%- for row in rows %}
		<tr>
			<td>{{ _(row.element_type) | e }}</td>
			<td>{{ row.reference_name | e }}</td>
			<td>{{ (row.title or "") | e }}</td>
			<td>{{ (row.pinned_revision or "") | e }}{% if row.stale %} <span class="mds-stale">· {{ _("changed since approval") }}: {{ (row.change_note or "") | e }}</span>{% endif %}</td>
			<td>{{ (row.changed_under or "") | e }}</td>
		</tr>
		{%- endfor %}
	</table>
	{%- endif %}
	{%- endfor %}
	<h4>{{ _("Electronic signatures") }}</h4>
	{%- set signatures = signatures_for_print(doc) %}
	{%- if signatures %}
	<table>
		<tr><th>{{ _("Meaning") }}</th><th>{{ _("Signed by") }}</th><th>{{ _("Date and time") }}</th><th>{{ _("Act and reason") }}</th></tr>
		{%- for s in signatures %}
		<tr>
			<td>{{ _(s.meaning) | e }}</td>
			<td>{{ s.signer_name | e }} ({{ s.signer | e }})</td>
			<td>{{ frappe.utils.format_datetime(s.signed_at) }}</td>
			<td>{{ _(s.action) | e }}{% if s.reason %} · {{ s.reason | e }}{% endif %}</td>
		</tr>
		{%- endfor %}
	</table>
	{%- else %}
	<p>{{ _("Not yet signed.") }}</p>
	{%- endif %}
</div>
